	nextID int
}

func NewStore() *Store {
	return &Store{}
}

func (s *Store) Create(name string) Item {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.nextID++
	item := Item{
		ID:   strconv.Itoa(s.nextID),
